let manualDraft={L:1200,D:1000,palletHeight:150,tare:25,layerCount:1,stackVerified:false,boxes:[],requested:{}},manualActive=0,manualSelected=null,lastManualBatch=null,manualHistory=[],manualDrag=null;
try{const d=JSON.parse(localStorage.getItem('lg-manual-draft-v1'));if(d){ManualPallet.schema(d);manualDraft=d;}}catch{}
const manualClone=x=>JSON.parse(JSON.stringify(x));
function manualBefore(){manualHistory.push(manualClone(manualDraft));if(manualHistory.length>30)manualHistory.shift();}
function manualChanged(){lastManualBatch=null;$('mbatch').replaceChildren();if(vehicleReport?.inputs.manual)invalidateVehiclePlan();manualDraft.stackVerified=$('mverified').checked;persist('lg-manual-draft-v1',manualDraft);manualRender();}
function manualTry(fn){try{$('merror').textContent='';fn();}catch(e){$('merror').textContent=e.message;}}
function manualSvg(t,layer,editable=false){const m=ManualPallet.metrics(t),pad=180,minX=m.footprint.minX-pad,minY=m.footprint.minY-pad,W=m.footprint.L+pad*2,H=m.footprint.D+pad*2;return {viewBox:`${minX} ${minY} ${W} ${H}`,html:`<rect x="0" y="0" width="${t.L}" height="${t.D}" fill="#f2f5ed" stroke="#53715a" stroke-width="8" stroke-dasharray="25 15"/>${t.boxes.filter(b=>b.layer===layer).map(b=>`<g ${editable?`data-box="${esc(b.id)}"`:''}><rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.d}" fill="${m.invalidBoxIds.includes(b.id)?'#edb4a8':'#bad1a7'}" stroke="${manualSelected===b.id?'#163e2c':'#658653'}" stroke-width="${manualSelected===b.id?12:4}"/><text pointer-events="none" x="${b.x+b.w/2}" y="${b.y+b.d/2}" dominant-baseline="middle" text-anchor="middle" font-size="${Math.min(44,b.w/Math.max(b.model.length,8)*1.3,b.d/4)}">${esc(b.model)}</text><text pointer-events="none" x="${b.x+b.w/2}" y="${b.y+b.d/2+55}" text-anchor="middle" font-size="28">${b.w} × ${b.d}</text></g>`).join('')}<text x="0" y="-65" font-size="40">Pallet ${t.L} × ${t.D} mm</text>`};}
function manualRender(fit=true){const t=manualDraft,m=ManualPallet.metrics(t);manualActive=Math.min(manualActive,t.layerCount-1);for(const [id,k]of [['mL','L'],['mD','D'],['mBase','palletHeight'],['mTare','tare'],['mlayers','layerCount']])$(id).value=t[k];$('mverified').checked=t.stackVerified;$('mviewtitle').textContent=$('mviewmode').value==='3d'?`3D pallet · editing layer ${manualActive+1}`:`Layer ${manualActive+1} · top view`;$('mlayertabs').innerHTML=Array.from({length:t.layerCount},(_,i)=>`<button class="${i===manualActive?'primary':'secondary'}" data-layer="${i}">${i+1}</button>`).join('');$('mlayertabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{manualActive=Number(b.dataset.layer);manualSelected=null;manualRender()});const drawing=$('mviewmode').value==='3d'?LoadScene3D.scene(LoadScene3D.palletBoxes({...t,boxes:t.boxes.map(b=>({...b,invalid:m.invalidBoxIds.includes(b.id)}))},manualSelected,manualActive),{angle:Number($('mcamera').value)}):manualSvg(t,manualActive,true);if(fit)$('mcanvas').setAttribute('viewBox',drawing.viewBox);$('mcanvas').innerHTML=drawing.html;$('mmetrics').innerHTML=`<div class="stats"><div class="stat"><strong>${+(m.height/10).toFixed(2)} cm</strong><span>Total loaded height</span></div><div class="stat"><strong>${m.totalBoxes}</strong><span>Boxes · ${m.weight} kg gross</span></div></div><p>Loaded footprint: <b>${m.footprint.L} × ${m.footprint.D} mm</b><br>Overhang left / right / front / back: ${Object.values(m.overhang).map(v=>+(v/10).toFixed(2)).join(' / ')} cm</p><p>${m.layers.map(l=>`Layer ${l.layer}: ${l.boxes} boxes · ${l.height} mm · top ${l.topHeight} mm`).join('<br>')}</p>${m.errors.length?`<p class="manualinvalid">${m.errors.map(esc).join('<br>')}</p>`:'<p>Geometry checks passed.</p>'}`;
const scale=1200/Math.max(m.height,1);$('mside').setAttribute('viewBox','0 0 1500 1400');let top=1300;$('mside').innerHTML=`<text x="0" y="50" font-size="50">SIDE HEIGHT · ${m.height} mm</text>`;for(const [h,label,color]of [[t.palletHeight,'Pallet','#ac9772'],...m.layers.filter(l=>l.boxes).map(l=>[l.height,'Layer '+l.layer,'#bad1a7'])]){top-=h*scale;$('mside').innerHTML+=`<rect x="0" y="${top}" width="1000" height="${h*scale}" fill="${color}" stroke="white" stroke-width="5"/><text x="1020" y="${top+h*scale/2}" font-size="40">${label}: ${h} mm</text>`;}
const b=t.boxes.find(b=>b.id===manualSelected);$('mselected').innerHTML=b?`<b>${esc(b.model)} · ${b.w/10} × ${b.d/10} × ${b.h/10} cm</b><div class="fields two"><label>X position cm<input id="mboxx" type="number" step="0.1" value="${b.x/10}"></label><label>Y position cm<input id="mboxy" type="number" step="0.1" value="${b.y/10}"></label><label>Move to layer<input id="mboxlayer" type="number" min="1" max="${t.layerCount}" value="${b.layer+1}"></label></div><p class="muted">Selected box overhang: left ${Math.max(0,-b.x)/10} / right ${Math.max(0,b.x+b.w-t.L)/10} / front ${Math.max(0,-b.y)/10} / back ${Math.max(0,b.y+b.d-t.D)/10} cm</p><div class="fields two"><label>Overhang edge<select id="medge"><option value="left">Left</option><option value="right">Right</option><option value="front">Front</option><option value="back">Back</option></select></label><label>Outside pallet (cm)<input id="moutside" type="number" min="0" max="1000" step="0.1" value="10"></label></div><div class="actions"><button id="msetoutside" class="secondary">Apply overhang</button><button id="mcenter" class="secondary">Center box</button></div>`:'Select a box to edit its position in cm.';
if(b){for(const [id,k]of [['mboxx','x'],['mboxy','y']])$(id).onchange=()=>manualTry(()=>{const n=Number($(id).value)*10;if(!Number.isFinite(n)||Math.abs(n)>10000)throw Error('Coordinates must be within ±1,000 cm.');manualBefore();b[k]=n;manualChanged()});$('mboxlayer').onchange=()=>manualTry(()=>{const layer=Number($('mboxlayer').value)-1;if(!Number.isInteger(layer)||layer<0||layer>=t.layerCount)throw Error('Choose an existing layer.');manualBefore();b.layer=layer;manualActive=layer;$('mverified').checked=false;manualChanged()});$('msetoutside').onclick=()=>manualTry(()=>{const n=Number($('moutside').value)*10;if(!Number.isFinite(n)||n<0||n>10000)throw Error('Enter overhang from 0 to 1,000 cm.');manualBefore();const edge=$('medge').value;if(edge==='left')b.x=-n;if(edge==='right')b.x=t.L-b.w+n;if(edge==='front')b.y=-n;if(edge==='back')b.y=t.D-b.d+n;manualChanged()});$('mcenter').onclick=()=>{manualBefore();b.x=(t.L-b.w)/2;b.y=(t.D-b.d)/2;manualChanged()};}$('mrotate').disabled=$('mdelete').disabled=!b;
const models=Object.keys(m.counts);t.requested||={};for(const model of models)if(t.requested[model]===undefined)t.requested[model]=24;$('mquantities').innerHTML=models.map(model=>`<label>${esc(model)} · ${m.counts[model]} per full pallet<input data-total="${esc(model)}" type="number" min="0" max="100000" value="${t.requested?.[model]??24}"></label>`).join('');$('mquantities').querySelectorAll('input').forEach(input=>input.onchange=()=>{manualDraft.requested||={};manualDraft.requested[input.dataset.total]=Number(input.value);lastManualBatch=null;$('mbatch').replaceChildren();if(vehicleReport?.inputs.manual)invalidateVehiclePlan();persist('lg-manual-draft-v1',manualDraft)});}
function manualAdd(amount=null){const p=products.find(p=>p.model.toUpperCase()===$('mmodel').value.trim().toUpperCase());if(!p||!ready(p)||p.bundle)throw Error('Select a model with complete packaged dimensions and gross weight, or add your own product.');const n=amount??Number($('mcount').value);if(!Number.isInteger(n)||n<1||n>30||manualDraft.boxes.length+n>300)throw Error('Add 1–30 boxes at once, up to 300 in a design.');manualBefore();for(let i=0;i<n;i++){const [w,d,h]=p.dims,others=manualDraft.boxes.filter(b=>b.layer===manualActive);let b={id:crypto.randomUUID(),model:p.model,w,d,h,weight:p.weight,layer:manualActive,x:(manualDraft.L-w)/2,y:(manualDraft.D-d)/2};const xs=[0,...others.map(o=>o.x+o.w)],ys=[0,...others.map(o=>o.y+o.d)];let found=false;for(const y of ys){for(const x of xs){const test={...b,x,y};if(x+w<=manualDraft.L+100&&y+d<=manualDraft.D+100&&!others.some(o=>ManualPallet.overlap(o,test))){b=test;found=true;break;}}if(found)break;}if(!others.length){b.x=(manualDraft.L-w)/2;b.y=(manualDraft.D-d)/2;}if(!found&&others.length)b.x=Math.max(...others.map(o=>o.x+o.w))+20;manualDraft.boxes.push(b);manualSelected=b.id;}manualDraft.stackVerified=false;$('mverified').checked=false;manualChanged();}
$('madd').onclick=()=>manualTry(manualAdd);$('mcustom').onclick=()=>edit(null);
for(const [id,k]of [['mL','L'],['mD','D'],['mBase','palletHeight'],['mTare','tare'],['mlayers','layerCount']])$(id).onchange=()=>manualTry(()=>{const next={...manualDraft,[k]:Number($(id).value)};ManualPallet.schema(next);manualBefore();manualDraft=next;manualChanged()});
$('mpreset').onchange=()=>{if($('mpreset').value==='custom')return;manualBefore();manualDraft.L=1200;manualDraft.D=$('mpreset').value==='euro'?800:1000;manualChanged()};
$('mquick').innerHTML=[1,2,3,4,5,6].map(n=>`<button class="secondary" data-n="${n}">${n} layers</button>`).join('');$('mquick').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('mlayers').value=b.dataset.n;$('mlayers').onchange()});
$('mcopy').onclick=()=>manualTry(()=>{const boxes=manualDraft.boxes.filter(b=>b.layer===manualActive);if(!boxes.length)throw Error('Add boxes to this layer first.');if(manualActive>=49||manualDraft.boxes.length+boxes.length>300)throw Error('Design limit reached.');if(manualDraft.boxes.some(b=>b.layer===manualActive+1))throw Error('The next layer already has boxes. Select or clear it first.');manualBefore();manualDraft.layerCount=Math.max(manualDraft.layerCount,manualActive+2);manualDraft.boxes.push(...boxes.map(b=>({...b,id:crypto.randomUUID(),layer:manualActive+1})));manualActive++;$('mverified').checked=false;manualChanged()});
$('mrotate').onclick=()=>{const b=manualDraft.boxes.find(b=>b.id===manualSelected);if(b){manualBefore();const cx=b.x+b.w/2,cy=b.y+b.d/2;[b.w,b.d]=[b.d,b.w];b.x=cx-b.w/2;b.y=cy-b.d/2;manualChanged()}};$('mdelete').onclick=()=>{manualBefore();manualDraft.boxes=manualDraft.boxes.filter(b=>b.id!==manualSelected);manualSelected=null;manualChanged()};$('mundo').onclick=()=>{if(manualHistory.length){manualDraft=manualHistory.pop();$('mverified').checked=manualDraft.stackVerified;manualChanged()}};$('mverified').onchange=manualChanged;
function manualPoint(e){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform($('mcanvas').getScreenCTM().inverse());return $('mviewmode').value==='3d'?LoadScene3D.camera(Number($('mcamera').value)).unproject(p.x,p.y):p;}
$('mcanvas').onpointerdown=e=>{const id=e.target.closest('[data-box]')?.dataset.box;if(!id)return;const b=manualDraft.boxes.find(b=>b.id===id);manualBefore();manualSelected=id;manualActive=b.layer;const p=manualPoint(e);manualDrag={id,dx:p.x-b.x,dy:p.y-b.y};$('mcanvas').setPointerCapture(e.pointerId);manualRender(false)};
$('mcanvas').onpointermove=e=>{if(!manualDrag)return;const b=manualDraft.boxes.find(b=>b.id===manualDrag.id),p=manualPoint(e);b.x=Math.max(-10000,Math.min(10000,Math.round((p.x-manualDrag.dx)/10)*10));b.y=Math.max(-10000,Math.min(10000,Math.round((p.y-manualDrag.dy)/10)*10));manualRender(false)};
for(const event of ['pointerup','pointercancel'])$('mcanvas').addEventListener(event,()=>{if(manualDrag){manualDrag=null;manualChanged()}});
$('mexport').onclick=()=>download('manual-pallet-design.json',manualDraft);$('mimport').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());ManualPallet.schema(d);manualBefore();manualDraft=d;manualActive=0;$('mverified').checked=d.stackVerified;manualChanged()}catch(error){$('merror').textContent=error.message}e.target.value=''};
function manualBuild(){lastManualBatch=ManualPallet.repeat(manualDraft,manualDraft.requested||{});manualBatchRender();}
function manualBatchRender(){const b=lastManualBatch;if(!b)return;$('mbatch').innerHTML=`<h3>${b.pallets.length} pallets · ${b.totalCartons} cartons</h3><p>${b.fullPallets} identical full pallets + ${b.partialPallets} partial pallets · ${b.totalGrossWeight} kg gross</p><label>Inspect pallet<select id="mbatchselect">${b.pallets.map(p=>`<option value="${p.number-1}">Pallet ${p.number} · ${p.partial?'PARTIAL':'full'} · ${p.units} boxes · ${p.height} mm</option>`).join('')}</select></label><label hidden>Inspect layer<select id="mbatchlayer"></select></label><svg id="mbatchcanvas" class="manualcanvas" role="img" aria-label="Completed pallet preview"></svg><div id="mbatchdetails"></div><p class="muted">${esc(b.method)}</p><button id="mvehicles" class="primary">Show pallets in Dyna / lorry / trailer ↗</button><button id="mbatchexport" class="secondary">Export pallet batch</button>`;$('mbatchselect').onchange=()=>{const p=b.pallets[Number($('mbatchselect').value)];$('mbatchlayer').innerHTML=Array.from({length:p.layers},(_,i)=>`<option value="${i}">Layer ${i+1}</option>`).join('');preview()};function preview(){const p=b.pallets[Number($('mbatchselect').value)],t={...b.template,boxes:p.boxes,layerCount:p.layers},s=LoadScene3D.scene(LoadScene3D.palletBoxes(t),{angle:35});$('mbatchcanvas').setAttribute('viewBox',s.viewBox);$('mbatchcanvas').innerHTML=s.html;$('mbatchdetails').textContent=Object.entries(p.counts).map(([m,q])=>m+' × '+q).join(' · ')+` · ${p.grossWeight} kg · ${p.loadedFootprint.L} × ${p.loadedFootprint.D} × ${p.height} mm`;} $('mbatchlayer').onchange=preview;$('mbatchselect').onchange();$('mvehicles').onclick=()=>{tab('vehicles');$('vehiclemode').value='custom';compareVehicleShipment()};$('mbatchexport').onclick=()=>download('manual-pallet-batch.json',b);}
$('mbuild').onclick=()=>manualTry(manualBuild);
function manualVehicleReport(profiles){if(!lastManualBatch)throw Error('Build your 3D pallet batch first.');return VehiclePlanner.compareItems(ManualPallet.vehicleItems(lastManualBatch),profiles,{batch:lastManualBatch},vehicleOptions());}
function restoreManualBatch(batch){ManualPallet.schema(batch.template);manualDraft=manualClone(batch.template);lastManualBatch=ManualPallet.repeat(manualDraft,batch.requested);manualActive=0;manualRender();manualBatchRender();}
$('mviewmode').onchange=()=>manualRender();$('mcamera').oninput=()=>manualRender();
let manualAutoModel='';
$('mmodel').oninput=()=>manualTry(()=>{const value=$('mmodel').value.trim().toUpperCase();if(value===manualAutoModel)return;const p=products.find(p=>p.model.toUpperCase()===value);if(!p){manualAutoModel='';return;}manualAdd(1);manualAutoModel=value;});
$('mmodel').onchange=$('mmodel').oninput;
$('mboxquick').innerHTML='<span class="muted">Selected model · boxes in this layer</span>'+[1,2,3,4,5,6].map(n=>`<button class="secondary" data-boxcount="${n}">${n} box${n>1?'es':''}</button>`).join('');
$('mboxquick').querySelectorAll('button').forEach(button=>button.onclick=()=>manualTry(()=>manualArrangeCount(Number(button.dataset.boxcount))));
function manualArrangeCount(n){const p=products.find(p=>p.model.toUpperCase()===$('mmodel').value.trim().toUpperCase());if(!p||!ready(p)||p.bundle)throw Error('Select a model with shipping dimensions first.');const keep=manualDraft.boxes.filter(b=>b.layer!==manualActive||b.model!==p.model);if(keep.length+n>300)throw Error('Design limit: 300 boxes.');manualBefore();const positions=LoadScene3D.arrange(p.dims[0],p.dims[1],n,manualDraft.L,manualDraft.D);manualDraft.boxes=[...keep,...positions.map(pos=>({...pos,id:crypto.randomUUID(),model:p.model,h:p.dims[2],weight:p.weight,layer:manualActive}))];manualSelected=manualDraft.boxes.at(-1).id;$('mverified').checked=false;manualChanged();}
manualRender();
